const body = $input.first().json.body || {};
const questions = body.questions || [];
const userAnswers = body.user_answers || [];

let correctCount = 0;
let wrongCount = 0;
const detailedResults = [];
const wrongQuestionsList = [];

questions.forEach((q, index) => {
  const userAnsObj = userAnswers.find(a => a.question_index === index);
  const selectedOption = userAnsObj ? userAnsObj.selected_option : null;
  const isCorrect = selectedOption === q.correct_answer;

  if (isCorrect) {
    correctCount++;
  } else {
    wrongCount++;
    wrongQuestionsList.push({
      question: q.question,
      wrong_selected: selectedOption || 'Cevaplanmadı',
      correct_answer: q.correct_answer,
      explanation: q.explanation || ''
    });
  }

  detailedResults.push({
    question_index: index,
    question: q.question,
    selected_option: selectedOption,
    correct_answer: q.correct_answer,
    is_correct: isCorrect,
    explanation: q.explanation || ''
  });
});

const totalQuestions = questions.length;
const score = totalQuestions > 0 ? Math.round((correctCount / totalQuestions) * 100) : 0;

let recommendationText = '';
if (wrongCount === 0 && totalQuestions > 0) {
  recommendationText = 'Harika bir başarı! Tüm soruları eksiksiz doğru yanıtladınız. Bu konuyu mükemmel kavramışsınız, bir sonraki üniteye güvenle geçebilirsiniz.';
} else {
  const prompt = `Sen motive edici bir eğitim danışmanı yapay zekâsısın. Bir öğrenci çözdüğü testte ${totalQuestions} sorudan ${correctCount} doğru, ${wrongCount} yanlış yaptı (Puan: ${score}). Yanlış yaptığı sorular ve konular: ${JSON.stringify(wrongQuestionsList)}. Öğrenciye eksik olduğu bu özel konulara yönelik yapıcı, motive edici ve nokta atışı 2-3 cümlelik bir çalışma tavsiyesi ve konu tekrar önerisi yaz. Yalnızca Türkçe tavsiye metnini döndür.`;

  const ollamaRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ollama:11434/api/generate',
    body: {
      model: 'qwen2.5:3b',
      prompt: prompt,
      stream: false
    },
    json: true
  });

  recommendationText = (ollamaRes.response || '').trim() || 'Eksik olduğunuz konuları pekiştirmek için ders notlarını tekrar gözden geçirmeniz önerilir.';
}

return {
  json: {
    success: true,
    total_questions: totalQuestions,
    correct_count: correctCount,
    wrong_count: wrongCount,
    score: score,
    detailed_results: detailedResults,
    recommendations: recommendationText,
    timestamp: new Date().toISOString()
  }
};
